starter:
def rectangle_report(a, b):
    # Write your code here.
    pass

solution:
def rectangle_report(a, b):
    if a <= 0 or b <= 0:
        return {"area": 0, "perimeter": 0}
    return {"area": a * b, "perimeter": perimeter(a, b)}

tests:
assert rectangle_report(3,4)=={"area":12,"perimeter":14}
assert rectangle_report(0,4)=={"area":0,"perimeter":0}
assert rectangle_report(-2,4)=={"area":0,"perimeter":0}
assert rectangle_report(1.5,2)=={"area":3.0,"perimeter":7.0}

